import fs from 'fs';
import path from 'path';
import type { ChildProcess } from 'child_process';
import { createLogger } from '../utils/logger';
import { previewDependencies } from './DependencyPreparationService';
import type { VariantHistoryService } from './VariantHistoryService';
import { PreviewEnvironment } from './PreviewEnvironment';
import { errorMessage } from '../utils/errorMessage';

const log = createLogger('HistoryReplayService');

const DEFAULT_IDLE_TTL_MS = 30 * 60 * 1000;
const DEFAULT_MAX_ACTIVE_REPLAYS = 6;
const REPLAY_PORT_SCAN_START = 3000;
const PORT_PLACEHOLDER = '${PORT}';

export interface ReplayDevServerManager {
  findFreePortFrom(startPort: number): Promise<number>;
  releasePort?(port: number): void;
  startDevServer(
    worktreePath: string,
    port: number,
    cmd: string,
    args: string[],
    env: Record<string, string>,
  ): Promise<ChildProcess>;
  stopDevServer(proc: ChildProcess, timeoutMs?: number): Promise<void>;
}

export class HistoryReplayError extends Error {
  constructor(
    readonly code: 'REPLAY_UNAVAILABLE' | 'REPLAY_START_FAILED',
    message: string,
  ) {
    super(message);
    this.name = 'HistoryReplayError';
  }
}

interface ActiveReplay {
  commitSha: string;
  key: string;
  sessionId: string;
  variantId: string;
  projectPath: string;
  worktreePath: string;
  port: number;
  proc: ChildProcess;
  idleTimer: NodeJS.Timeout;
}

export class HistoryReplayService {
  private readonly history: VariantHistoryService;
  private readonly devServers: ReplayDevServerManager;
  private readonly switchPreviewPort?: (port: number | null) => void;
  private readonly idleTtlMs: number;
  private readonly maxActiveReplays: number;
  private readonly replays = new Map<string, ActiveReplay>();
  private readonly stoppedWorkspaces = new Map<
    string,
    { projectPath: string; worktreePath: string; commitSha: string }
  >();
  private readonly environment = new PreviewEnvironment();
  private globalProxyKey: string | null = null;
  private transition: Promise<unknown> = Promise.resolve();

  constructor(deps: {
    history: VariantHistoryService;
    devServers: ReplayDevServerManager;
    switchPreviewPort?: (port: number | null) => void;
    idleTtlMs?: number;
    maxActiveReplays?: number;
  }) {
    this.history = deps.history;
    this.devServers = deps.devServers;
    this.switchPreviewPort = deps.switchPreviewPort;
    this.idleTtlMs = deps.idleTtlMs ?? DEFAULT_IDLE_TTL_MS;
    this.maxActiveReplays = Math.max(
      1,
      deps.maxActiveReplays ?? DEFAULT_MAX_ACTIVE_REPLAYS,
    );
  }

  current(): { sessionId: string; variantId: string; port: number } | null {
    const replay = this.globalProxyKey
      ? this.replays.get(this.globalProxyKey)
      : null;
    if (!replay) return null;
    return {
      sessionId: replay.sessionId,
      variantId: replay.variantId,
      port: replay.port,
    };
  }

  getPort(sessionId: string, variantId: string): number | null {
    const replay = this.replays.get(replayKey(sessionId, variantId));
    if (!replay) return null;
    this.touch(replay);
    return replay.port;
  }

  async run(args: {
    projectPath: string;
    sessionId: string;
    variantId: string;
    retargetProxy?: boolean;
  }): Promise<{ port: number; alreadyRunning: boolean }> {
    return this.enqueue(async () => {
      const key = replayKey(args.sessionId, args.variantId);
      const shouldRetargetProxy = args.retargetProxy ?? true;
      const existing = this.replays.get(key);
      if (existing) {
        this.touch(existing);
        if (shouldRetargetProxy) {
          this.globalProxyKey = key;
          this.switchPreviewPort?.(existing.port);
        }
        return { port: existing.port, alreadyRunning: true };
      }

      const detail = await this.history.getVariant(args);
      const manifest = detail?.manifest;
      if (!manifest?.tree) {
        throw new HistoryReplayError(
          'REPLAY_UNAVAILABLE',
          `Variant ${args.variantId} has no tree snapshot — legacy history entries can't be replayed`,
        );
      }
      if (manifest.serve?.kind !== 'dev-server') {
        throw new HistoryReplayError(
          'REPLAY_UNAVAILABLE',
          `Variant ${args.variantId} has no dev-server recipe (serve: ${manifest.serve?.kind ?? 'none'})`,
        );
      }
      const recipe = manifest.serve.recipe;

      const store = this.history.store;
      let worktreePath: string | null = null;
      let port: number | undefined;
      try {
        const stopped = this.stoppedWorkspaces.get(key);
        this.stoppedWorkspaces.delete(key);
        if (
          stopped &&
          stopped.projectPath === args.projectPath &&
          stopped.commitSha === manifest.tree.commitSha &&
          fs.existsSync(stopped.worktreePath)
        ) {
          worktreePath = stopped.worktreePath;
        } else {
          if (stopped)
            await this.cleanupWorktree(
              stopped.projectPath,
              stopped.worktreePath,
            );
          worktreePath = await store.materializeWorktree(
            args.projectPath,
            manifest.tree.commitSha,
          );
        }
        await this.environment.prepare({
          projectPath: args.projectPath,
          worktreePath,
          cwd: recipe.cwd,
        });
        await previewDependencies.prepare({
          cwd: path.resolve(worktreePath, recipe.cwd),
          workspaceRoot: worktreePath,
          packageManagerCommand: recipe.cmd,
        });

        port = await this.devServers.findFreePortFrom(REPLAY_PORT_SCAN_START);
        const boundPort = port;
        const cwd = path.resolve(worktreePath, recipe.cwd);
        const proc = await this.devServers.startDevServer(
          cwd,
          boundPort,
          recipe.cmd,
          substitutePort(recipe.argsTemplate, boundPort),
          Object.fromEntries(
            Object.entries(recipe.envTemplate ?? {}).map(([k, v]) => [
              k,
              substitutePortValue(v, boundPort),
            ]),
          ),
        );
        this.devServers.releasePort?.(boundPort);

        const replay: ActiveReplay = {
          commitSha: manifest.tree.commitSha,
          key,
          sessionId: args.sessionId,
          variantId: args.variantId,
          projectPath: args.projectPath,
          worktreePath,
          port,
          proc,
          idleTimer: setTimeout(
            () =>
              void this.stop({
                sessionId: args.sessionId,
                variantId: args.variantId,
              }),
            this.idleTtlMs,
          ),
        };
        proc.once('exit', () => {
          if (this.replays.get(key) !== replay) return;
          log.warn(`Replay dev server for ${key} exited unexpectedly`);
          clearTimeout(replay.idleTimer);
          this.replays.delete(key);
          if (this.globalProxyKey === key) {
            this.globalProxyKey = null;
            this.switchPreviewPort?.(null);
          }
          void this.enqueue(() =>
            this.cleanupWorktree(args.projectPath, replay.worktreePath),
          );
        });
        this.replays.set(key, replay);
        if (shouldRetargetProxy) {
          this.globalProxyKey = key;
          this.switchPreviewPort?.(port);
        }
        await this.enforceReplayLimit(key);
        return { port, alreadyRunning: false };
      } catch (err) {
        if (port !== undefined) this.devServers.releasePort?.(port);
        if (worktreePath) {
          await this.cleanupWorktree(args.projectPath, worktreePath);
        }
        if (shouldRetargetProxy) {
          this.globalProxyKey = null;
          this.switchPreviewPort?.(null);
        }
        if (err instanceof HistoryReplayError) throw err;
        throw new HistoryReplayError('REPLAY_START_FAILED', errorMessage(err));
      }
    });
  }

  async stop(args?: { sessionId: string; variantId: string }): Promise<void> {
    await this.enqueue(async () => {
      if (args) {
        await this.stopReplay(replayKey(args.sessionId, args.variantId), {
          retainWorkspace: true,
        });
        return;
      }
      await this.stopAllReplays();
      for (const stopped of this.stoppedWorkspaces.values()) {
        await this.cleanupWorktree(stopped.projectPath, stopped.worktreePath);
      }
      this.stoppedWorkspaces.clear();
    });
  }

  async shutdown(): Promise<void> {
    await this.stop();
  }

  private async stopReplay(
    key: string,
    opts: { retargetProxy?: boolean; retainWorkspace?: boolean } = {},
  ): Promise<void> {
    const replay = this.replays.get(key);
    if (!replay) return;
    this.replays.delete(key);
    clearTimeout(replay.idleTimer);
    try {
      await this.devServers.stopDevServer(replay.proc);
    } catch (err) {
      log.warn(`Failed to stop replay dev server for ${replay.key}`, err);
    }
    if (opts.retargetProxy !== false && this.globalProxyKey === key) {
      this.globalProxyKey = null;
      this.switchPreviewPort?.(null);
    }
    if (opts.retainWorkspace) {
      this.stoppedWorkspaces.set(key, {
        projectPath: replay.projectPath,
        worktreePath: replay.worktreePath,
        commitSha: replay.commitSha,
      });
      while (this.stoppedWorkspaces.size > this.maxActiveReplays) {
        const oldest = this.stoppedWorkspaces.entries().next().value;
        if (!oldest) break;
        this.stoppedWorkspaces.delete(oldest[0]);
        await this.cleanupWorktree(
          oldest[1].projectPath,
          oldest[1].worktreePath,
        );
      }
    } else {
      await this.cleanupWorktree(replay.projectPath, replay.worktreePath);
    }
  }

  private async stopAllReplays(): Promise<void> {
    const keys = Array.from(this.replays.keys());
    for (const key of keys) {
      await this.stopReplay(key);
    }
  }

  private touch(replay: ActiveReplay): void {
    clearTimeout(replay.idleTimer);
    replay.idleTimer = setTimeout(
      () =>
        void this.stop({
          sessionId: replay.sessionId,
          variantId: replay.variantId,
        }),
      this.idleTtlMs,
    );
    this.replays.delete(replay.key);
    this.replays.set(replay.key, replay);
  }

  private async enforceReplayLimit(protectedKey: string): Promise<void> {
    while (this.replays.size > this.maxActiveReplays) {
      const candidates = Array.from(this.replays.keys()).filter(
        (key) => key !== protectedKey,
      );
      const evictKey =
        candidates.find((key) => key !== this.globalProxyKey) ?? candidates[0];
      if (!evictKey) return;
      await this.stopReplay(evictKey);
    }
  }

  private async cleanupWorktree(
    projectPath: string,
    worktreePath: string,
  ): Promise<void> {
    try {
      this.environment.forget(worktreePath);
      previewDependencies.forget(worktreePath);
      await this.history.store.removeWorktree(projectPath, worktreePath);
    } catch (err) {
      log.warn(`Failed to remove replay worktree ${worktreePath}`, err);
    }
  }

  private enqueue<T>(task: () => Promise<T>): Promise<T> {
    const next = this.transition.catch(() => undefined).then(task);
    this.transition = next.catch(() => undefined);
    return next;
  }
}

const substitutePortValue = (value: string, port: number): string =>
  value.split(PORT_PLACEHOLDER).join(String(port));

const substitutePort = (args: string[], port: number): string[] =>
  args.map((arg) => substitutePortValue(arg, port));

const replayKey = (sessionId: string, variantId: string): string =>
  `${sessionId}:${variantId}`;
